const purple = Color(0xFF6D27C7);
const lavender = Color(0xFFF2ECFF);
const deepPurple = Color(0xFF4A148C);
const demoMode = bool.fromEnvironment('DEMO_MODE', defaultValue: false);
const supabaseUrl = String.fromEnvironment('SUPABASE_URL');
const supabaseAnonKey = String.fromEnvironment('SUPABASE_ANON_KEY');

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  if (!demoMode && supabaseUrl.isNotEmpty && supabaseAnonKey.isNotEmpty) {
    await Supabase.initialize(url: supabaseUrl, anonKey: supabaseAnonKey);
  }
  runApp(const FmlyCraftApp());
}

class FmlyCraftApp extends StatelessWidget {
  const FmlyCraftApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'FMLY CRAFT',
    theme: ThemeData(
      colorScheme: ColorScheme.fromSeed(seedColor: purple, brightness: Brightness.light),
      scaffoldBackgroundColor: Colors.white,
      useMaterial3: true,
      fontFamily: 'sans',
      inputDecorationTheme: InputDecorationTheme(
        filled: true, fillColor: const Color(0xFFF8F5FC),
        border: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide.none),
        focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: const BorderSide(color: purple)),
      ),
      elevatedButtonTheme: ElevatedButtonThemeData(style: ElevatedButton.styleFrom(
        backgroundColor: purple, foregroundColor: Colors.white, minimumSize: const Size.fromHeight(52),
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
      )),
    ),
    home: const SplashPage(),
  );
}

class Product {
  final String id, name, description, category, image;
  final int price, mrp, stock;
  final double rating;
  const Product({required this.id, required this.name, required this.description, required this.category, required this.image, required this.price, required this.mrp, required this.stock, this.rating=4.5});
  int get discount => mrp > 0 ? ((mrp-price)*100/mrp).round() : 0;
}

