  Product(id:'p1', name:'Decorative Flower Pot', description:'Beautiful decorative flower pot for your home and office. Premium home-decor finish.', category:'Plants & Pots', image:'https://images.unsplash.com/photo-1485955900006-10f4d324d411?w=900', price:299, mrp:399, stock:12),
