class CartStore extends ChangeNotifier {
  final Map<String,int> items = {};
  void add(Product p) { items[p.id] = (items[p.id] ?? 0)+1; notifyListeners(); }
  void remove(Product p) { if ((items[p.id] ?? 0)>1) items[p.id]=items[p.id]!-1; else items.remove(p.id); notifyListeners(); }
  int qty(Product p)=>items[p.id]??0;
  int get count=>items.values.fold(0,(a,b)=>a+b);
  int get subtotal=>items.entries.fold(0,(sum,e){final p=demoProducts.firstWhere((x)=>x.id==e.key); return sum+p.price*e.value;});
  void clear(){items.clear();notifyListeners();}
}
final cart = CartStore();

