class _CheckoutPageState extends State<CheckoutPage>{int method=0;bool checking=false;String address='';Future<void> validate() async {setState(()=>checking=true); try{LocationPermission p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission(); if(p==LocationPermission.denied||p==LocationPermission.deniedForever){throw Exception('Location permission is required to verify Chandigarh delivery area.');}final pos=await Geolocator.getCurrentPosition(); if(!(pos.latitude>30.65&&pos.latitude<30.80&&pos.longitude>76.68&&pos.longitude<76.90)){throw Exception('Sorry, FMLY CRAFT currently delivers only within Chandigarh.');} setState(()=>address='Current location verified inside Chandigarh');}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>checking=false);}} @override Widget build(BuildContext context){final total=cart.subtotal+20;return Scaffold(appBar:AppBar(title:const Text('Checkout')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(leading:const Icon(Icons.location_on,color:purple),title:Text(address.isEmpty?'Delivery Address':'Chandigarh Verified'),subtitle:Text(address.isEmpty?'Tap to verify your location':'$address'),trailing:IconButton(onPressed:checking?null:validate,icon:const Icon(Icons.my_location)))),const SizedBox(height:12),const Text('Delivery Option',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),RadioListTile(value:0,groupValue:method,onChanged:(v)=>setState(()=>method=v!),title:const Text('Normal Delivery'),subtitle:const Text('₹20 • within 2–4 hours')),RadioListTile(value:1,groupValue:method,onChanged:(v)=>setState(()=>method=v!),title:const Text('Fast Delivery'),subtitle:const Text('+₹10 • within 1–2 hours')),RadioListTile(value:2,groupValue:method,onChanged:(v)=>setState(()=>method=v!),title:const Text('Express Delivery'),subtitle:const Text('+₹20 • within 30–60 minutes')),const SizedBox(height:10),const Text('Payment Method',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),RadioListTile(value:0,groupValue:0,onChanged:(_){},title:const Text('Online Payment'),subtitle:const Text('UPI, Card, Net Banking')),RadioListTile(value:1,groupValue:0,onChanged:(_){},title:const Text('Cash on Delivery'),subtitle:Text(total>=100?'Available':'Available only for configured minimum amount')),const SizedBox(height:14),Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:lavender,borderRadius:BorderRadius.circular(16)),child:Column(children:[Row(children:[const Text('Final Amount',style:TextStyle(fontWeight:FontWeight.w800)),const Spacer(),Text('₹${total+(method==1?10:method==2?20:0)}',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900,color:deepPurple))])])),const SizedBox(height:16),ElevatedButton(onPressed:address.isEmpty?validate:()=>Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const OrderSuccessPage())),child:Text(address.isEmpty?'Verify Chandigarh Address':'Place Order'))]));}}

